155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        // Validate & normalize the optional email; reject the create when it is present but invalid.
159	        if (!normalizeEmail(ownerFieldsDto)) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        // Validate & normalize the optional postcode; reject the create when it is present but
163	        // not valid for the owner's city (see normalizePostcode).
164	        if (!normalizePostcode(ownerFieldsDto)) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
168	        // abbreviations) and store the normalized form back on the DTO so it is what gets
169	        // persisted and compared. Reject the create when the address is blank once normalized.
170	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
171	        if (canonicalAddress.isBlank()) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        ownerFieldsDto.setAddress(canonicalAddress);
175	        // Reject the create when the owner's city is already at capacity, i.e. it already
176	        // contains 50 or more owners (compared case-insensitively).
177	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
179	        }
180	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
181	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
182	        if (normalizedTelephone == null) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        ownerFieldsDto.setTelephone(normalizedTelephone);
186	        // Consolidated duplicate detection. All former separate telephone, email and household
187	        // duplicate checks are now expressed through the single derived identity key
188	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
189	        // A create is rejected only when the new owner's identity collides with an existing owner's.
190	        // Because the telephone is part of the identity, two members of the same household with
191	        // different telephones no longer collide and are both allowed; only owners that share the
192	        // same normalized telephone and email are treated as the same identity.
193	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
194	        String contactIdentity = identityContact(candidate);
195	        boolean identityInUse = this.clinicService.findAllOwners().stream()
196	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
197	        if (identityInUse) {
198	            return new ResponseEntity<>(HttpStatus.CONFLICT);
199	        }
200	        // Household duplicate detection keyed on the deterministic householdId, derived from the
201	        // normalized last name and postcode (see OwnerMapper#householdId). Owners sharing a last
202	        // name and postcode share the same household. A second owner in an existing household is
203	        // rejected as a household duplicate (409) unless the request declares 'sharesHousehold',
204	        // in which case it is created as a declared household member — 'sharesHousehold' only
205	        // bypasses this block; the household link itself now follows from the computed householdId.
206	        String householdId = ownerMapper.householdId(candidate);
207	        boolean householdExists = this.clinicService.findAllOwners().stream()
208	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
209	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
210	        if (householdExists && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        boolean declaredMember = householdExists && sharesHousehold;
214	        // Determine the effective registration date — the value supplied on the request, or the
215	        // server's current date when none was supplied — and roll it forward to the next business
216	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
217	        // registration date (membership-number year segment, per-day create-limit) uses this
218	        // adjusted date.
219	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
220	        if (registrationDate == null) {
221	            registrationDate = LocalDate.now();
222	        }
223	        // Reject a supplied registration date that lies in the future (later than the
224	        // server's current date): an owner cannot be registered ahead of time.
225	        else if (registrationDate.isAfter(LocalDate.now())) {
226	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
227	        }
228	        registrationDate = toBusinessDay(registrationDate);
229	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
230	        // owners have already been registered on this (adjusted) business day.
231	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
232	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
233	        }
234	        HttpHeaders headers = new HttpHeaders();
235	        Owner owner = candidate;
236	        owner.setRegistrationDate(registrationDate);
237	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
238	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
239	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
240	        owner.setCustomerCode(customerCode(owner));
241	        // Record how many existing owners already share this owner's first and last name
242	        // (compared case-insensitively) at the moment before this owner is created.
243	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
244	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
245	        // registered on this (adjusted) business day before this owner is created.
246	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
247	        // Record the size of this owner's household after this create: the number of existing
248	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
249	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
250	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
251	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
252	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
253	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
254	        // duplicate. A declared household member is an acknowledged member, not a suspected
255	        // duplicate, so it is never flagged.
256	        if (declaredMember) {
257	            owner.setPossibleDuplicate(false);
258	            owner.setPossibleDuplicateOf(null);
259	        }
260	        else {
261	            Owner softMatch = findPossibleDuplicate(owner);
262	            owner.setPossibleDuplicate(softMatch != null);
263	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
264	        }
265	        this.clinicService.saveOwner(owner);
266	        // Emit an audit line recording the new owner's id, customer code, registration date
267	        // and membership level.
268	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
269	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
270	            ownerMapper.membershipLevel(owner));
271	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
272	        headers.setLocation(UriComponentsBuilder.newInstance()
273	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
274	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
275	    }
