277	    /**
278	     * Validate and normalize the optional owner email in place.
279	     *
280	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
281	     * When present it must be a syntactically valid address; a valid address is
282	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
283	     * present but syntactically invalid, so the caller can reject with 400.
284	     */
285	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
286	        String email = ownerFieldsDto.getEmail();
287	        if (email == null || email.isBlank()) {
288	            ownerFieldsDto.setEmail(null);
289	            return true;
290	        }
291	        String normalized = email.trim().toLowerCase(Locale.ROOT);
292	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
293	            return false;
294	        }
295	        // Reject addresses whose domain is on the disposable-domain blocklist.
296	        String domain = normalized.substring(normalized.indexOf('@') + 1);
297	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
298	            return false;
299	        }
300	        ownerFieldsDto.setEmail(normalized);
301	        return true;
302	    }
303	
304	    /**
305	     * Validate the optional owner postcode in place.
306	     *
307	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
308	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
309	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
310	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
311	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
312	     * when a postcode is present but malformed or out of range, so the caller can
313	     * reject with 400.
314	     */
315	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
316	        String postcode = ownerFieldsDto.getPostcode();
317	        if (postcode == null || postcode.isBlank()) {
318	            ownerFieldsDto.setPostcode(null);
319	            return true;
320	        }
321	        if (!postcode.matches("\\d{4}")) {
322	            return false;
323	        }
324	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
325	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
326	        if (range != null) {
327	            int value = Integer.parseInt(postcode);
328	            if (value < range[0] || value > range[1]) {
329	                return false;
330	            }
331	        }
332	        return true;
333	    }
334	
335	    /**
336	     * Normalize an owner address: trim, collapse each run of whitespace to a single
337	     * space, upper-case, and expand common street-type abbreviations
338	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
339	     * A {@code null} value normalizes to the empty string.
340	     */
341	    private static String normalizeAddress(String value) {
342	        if (value == null) {
343	            return "";
344	        }
345	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
346	        if (collapsed.isEmpty()) {
347	            return "";
348	        }
349	        String[] tokens = collapsed.split(" ");
350	        StringBuilder sb = new StringBuilder(collapsed.length());
351	        for (int i = 0; i < tokens.length; i++) {
352	            if (i > 0) {
353	                sb.append(' ');
354	            }
355	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
356	        }
357	        return sb.toString();
358	    }
359	
360	    /**
361	     * The contact portion of an owner's derived identity key: its normalized telephone and
362	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
363	     * without the household segment. Two owners share an identity when this value is equal;
364	     * because the telephone is part of it, members of one household with different telephones
365	     * do not collide. A {@code null} email contributes the empty string.
366	     */
367	    private static String identityContact(Owner owner) {
368	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
369	        String email = owner.getEmail() == null ? "" : owner.getEmail();
370	        return telephone + "|" + email;
371	    }
372	
373	    /**
374	     * Normalize a telephone number to E.164 form.
375	     *
376	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
377	     * explicit leading {@code '+'} and country code it is kept; otherwise the
378	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
379	     * dropped from the national digits. The result must contain 8 to 15 digits
380	     * after the {@code '+'}, and — for a recognised country calling code — exactly
381	     * the national-number length that code mandates ({@code '+61'} => 9 national
382	     * digits, {@code '+1'} => 10).
383	     *
384	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
385	     *         the input is absent or cannot form a valid E.164 number.
386	     */
387	    private static String toE164(String raw) {
388	        if (raw == null) {
389	            return null;
390	        }
391	        String trimmed = raw.trim();
392	        boolean hasCountryCode = trimmed.startsWith("+");
393	        // Strip spaces, dashes and brackets.
394	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
395	        String digits;
396	        if (hasCountryCode) {
397	            // Keep the explicit country code; drop the leading '+' for validation.
398	            digits = stripped.substring(1);
399	        } else {
400	            // No country code: assume '+61' and drop a single leading '0'.
401	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
402	            digits = "61" + national;
403	        }
404	        if (!digits.matches("\\d{8,15}")) {
405	            return null;
406	        }
407	        // For a recognised country calling code, enforce the exact national-number length it
408	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
409	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
410	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
411	                .sorted((a, b) -> b.length() - a.length()).toList()) {
412	            if (digits.startsWith(countryCode)) {
413	                int nationalLength = digits.length() - countryCode.length();
414	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
415	                    return null;
416	                }
417	                break;
418	            }
419	        }
420	        return "+" + digits;
421	    }
